/**
 * n8n Code node (Run Once for Each Item)
 *
 * IMPORTANTE:
 * - Formato preferido: `items` con nombre de producto + cantidad
 * - `cuentas` se mantiene SOLO por compatibilidad, pero pierde la categoría del producto
 *   y por eso no es el formato ideal para aplicar correctamente las reglas de empaque.
 *
 * Entrada por item (preferido):
 * {
 *   "items": [
 *     { "producto": "Cilindros", "cantidad": 320 },
 *     { "producto": "Sandalias Delgadas", "cantidad": 150 },
 *     { "producto": "Pantufla Moño Satin", "cantidad": 80 },
 *     { "producto": "Vaso Popote 24 oz", "cantidad": 50 },
 *     { "producto": "Mandiles", "cantidad": 20 }
 *   ]
 * }
 *
 * Compatibilidad (sin nombres):
 * { "cuentas": "50 x 0.15, 75 x 0.15" }
 *
 * Salida por item:
 * {
 *   "cajas": [
 *     {
 *       "indice": 1,
 *       "peso_total_kg": 18.75,
 *       "costo_envio": 350,
 *       "costo_envio_str": "$350",
 *       "contenido": { "Cilindros": 250, "Sandalias Delgadas": 50, "Pantufla Moño Satin": 0, "Otros_0kg": 20 }
 *     },
 *     ...
 *   ],
 *   "cantidad_cajas": 3,
 *   "costo_total_envio": 900,
 *   "costo_total_envio_str": "$900",
 *   "resumen_cajas": ["Caja 1: $350", "Caja 2: $300", "Caja 3: $250"]
 * }
 */

// ====== Config editable ======

// Pesos por producto (kg)
const WEIGHT_BY_PRODUCT = {
  "Mandiles": 0,
  "Kits Anticrudas": 0,
  "Costales": 0,

  "Cilindros": 0.14,
  "Vaso Popote 24 oz": 0.14,
  "Vasos Popote": 0.14,

  "Sandalias Delgadas": 0.15,
  "Sandalias Gruesas": 0.15,
  "Pantuflas": 0.15,
  "Pantuflas Mono": 0.15,
  "Pantufla Moño Satin": 0.15,
  "Pantufla Moño Peluche": 0.15
};

// Categoría por producto (para aplicar límites)
const CATEGORY_BY_PRODUCT = {
  "Cilindros": "CILINDROS",
  "Vaso Popote 24 oz": "CILINDROS",
  "Vasos Popote": "CILINDROS",

  "Sandalias Delgadas": "SANDALIAS",
  "Sandalias Gruesas": "SANDALIAS",
  "Pantuflas": "SANDALIAS",
  "Pantuflas Mono": "SANDALIAS",
  "Pantufla Moño Satin": "SANDALIAS",
  "Pantufla Moño Peluche": "SANDALIAS",

  // Los de 0 kg (sin restricciones explícitas)
  "Mandiles": "OTROS_0KG",
  "Kits Anticrudas": "OTROS_0KG",
  "Costales": "OTROS_0KG"
};

// Alias para tolerar variaciones del nombre que pueda mandar el agente
const PRODUCT_ALIASES = {
  "mandil": "Mandiles",
  "mandiles": "Mandiles",

  "kit anticruda": "Kits Anticrudas",
  "kits anticruda": "Kits Anticrudas",
  "kit anticrudas": "Kits Anticrudas",
  "kits anticrudas": "Kits Anticrudas",
  "costal": "Costales",
  "costales": "Costales",

  "cilindro": "Cilindros",
  "cilindros": "Cilindros",

  "sandalia delgada": "Sandalias Delgadas",
  "sandalias delgadas": "Sandalias Delgadas",
  "sandalia gruesa": "Sandalias Gruesas",
  "sandalias gruesas": "Sandalias Gruesas",

  "pantufla": "Pantuflas",
  "pantuflas": "Pantuflas",

  "pantufla mono": "Pantuflas Mono",
  "pantuflas mono": "Pantuflas Mono",
  "pantufla mono satin": "Pantufla Moño Satin",
  "pantuflas mono satin": "Pantufla Moño Satin",
  "pantufla mono satín": "Pantufla Moño Satin",
  "pantuflas mono satín": "Pantufla Moño Satin",
  "pantufla moño satin": "Pantufla Moño Satin",
  "pantuflas moño satin": "Pantufla Moño Satin",
  "pantufla moño satín": "Pantufla Moño Satin",
  "pantuflas moño satín": "Pantufla Moño Satin",

  "pantufla mono peluche": "Pantufla Moño Peluche",
  "pantuflas mono peluche": "Pantufla Moño Peluche",
  "pantufla moño peluche": "Pantufla Moño Peluche",
  "pantuflas moño peluche": "Pantufla Moño Peluche",

  "vaso popote": "Vaso Popote 24 oz",
  "vasos popote": "Vaso Popote 24 oz",
  "vaso popote 24 oz": "Vaso Popote 24 oz",
  "vasos popote 24 oz": "Vaso Popote 24 oz",
  "vaso con popote": "Vaso Popote 24 oz",
  "vasos con popote": "Vaso Popote 24 oz",
  "vaso con popote 24 oz": "Vaso Popote 24 oz",
  "vasos con popote 24 oz": "Vaso Popote 24 oz"
};

// Límites por caja
const LIMITS = {
  MAX_PER_BOX_WEIGHT_KG: 35,
  MAX_CILINDROS_PER_BOX: 250,
  MAX_SANDALIAS_PER_BOX: 200,
  MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX: 200
};

// Rangos de costo por peso total de la caja (kg)
// Nota: se respetan tus bordes tal cual
function costoPorPeso(pesoKg) {
  const p = Number(pesoKg.toFixed(2));
  if (p >= 0 && p <= 4.99) return 250;
  if (p >= 5 && p <= 7) return 280;
  if (p > 7.1 && p <= 12) return 300;
  if (p > 12.1 && p <= 19.99) return 350;
  if (p >= 20 && p <= 35) return 400;
  return null;
}

// ====== Utilidades ======

function normalizeText(str) {
  return String(str || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function canonicalizeProductName(rawName) {
  const clean = normalizeText(rawName);
  return PRODUCT_ALIASES[clean] || String(rawName || "").trim();
}

function parseItemsInput(rawItems) {
  if (Array.isArray(rawItems)) return rawItems;
  if (typeof rawItems === "string") {
    try {
      const parsed = JSON.parse(rawItems);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}
  }
  return null;
}

function cloneEmptyBoxState() {
  return {
    peso: 0,
    cil: 0,            // # Cilindros/Vasos en la caja
    sand: 0,           // # Sandalias/Pantuflas en la caja
    combSC: 0,         // combinadas sandalias + cilindros
    contenido: {}      // { producto: unidades }
  };
}

function addToBox(box, product, qty, weightPerUnit) {
  if (!box.contenido[product]) box.contenido[product] = 0;
  box.contenido[product] += qty;
  box.peso += qty * weightPerUnit;

  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  if (cat === "CILINDROS") {
    box.cil += qty;
    box.combSC += qty;
  } else if (cat === "SANDALIAS") {
    box.sand += qty;
    box.combSC += qty;
  }
}

function capacityForProductInBox(box, product, weightPerUnit) {
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  let cap = Infinity;

  // Peso
  if (weightPerUnit > 0) {
    const weightLeft = LIMITS.MAX_PER_BOX_WEIGHT_KG - box.peso;
    const byWeight = Math.floor(weightLeft / weightPerUnit);
    cap = Math.min(cap, Math.max(0, byWeight));
  }

  // Límites por categoría
  if (cat === "CILINDROS") {
    cap = Math.min(cap, LIMITS.MAX_CILINDROS_PER_BOX - box.cil);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "SANDALIAS") {
    cap = Math.min(cap, LIMITS.MAX_SANDALIAS_PER_BOX - box.sand);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "OTROS_0KG") {
    cap = Infinity;
  }

  return Math.max(0, cap);
}

// Empaquetado: “first-fit” con llenado por tandas
function packBoxes(orderLines) {
  const boxes = [];
  let currentBox = cloneEmptyBoxState();

  const lines = orderLines.slice().sort((a, b) => {
    const rank = (x) => {
      const cat = CATEGORY_BY_PRODUCT[x.product] || "OTROS";
      if (cat === "CILINDROS" || cat === "SANDALIAS") return 0;
      if (x.weight > 0) return 1;
      return 2;
    };
    const rA = rank(a), rB = rank(b);
    if (rA !== rB) return rA - rB;
    return (b.weight || 0) - (a.weight || 0);
  });

  const remaining = {};
  for (const ln of lines) {
    remaining[ln.product] = (remaining[ln.product] || 0) + ln.quantity;
  }

  function hasRemaining() {
    for (const k in remaining) {
      if (remaining[k] > 0) return true;
    }
    return false;
  }

  while (hasRemaining()) {
    let packedSomething = false;

    for (let i = 0; i < lines.length; i++) {
      const { product, weight } = lines[i];
      const need = remaining[product];
      if (!need) continue;

      const cap = capacityForProductInBox(currentBox, product, weight);
      if (cap <= 0) continue;

      const toPut = Math.min(need, cap);
      if (toPut > 0) {
        addToBox(currentBox, product, toPut, weight);
        remaining[product] -= toPut;
        packedSomething = true;
      }
    }

    if (!packedSomething || !hasRemaining()) {
      const hasContent = Object.keys(currentBox.contenido).length > 0;
      if (hasContent) {
        boxes.push(currentBox);
      }
      if (hasRemaining()) {
        currentBox = cloneEmptyBoxState();
      }
    }
  }

  return boxes;
}

// Traduce "cuentas" -> líneas genéricas (compatibilidad)
function orderFromCuentasStr(cuentasStr) {
  const parts = (cuentasStr || "").split(",");
  const map = {};

  for (let i = 0; i < parts.length; i++) {
    const expr = (parts[i] || "").trim();
    if (!expr) continue;

    const trozos = expr.split(/x|X|×|\*/);
    if (trozos.length < 2) continue;

    const a = parseFloat(String(trozos[0]).trim().replace(",", "."));
    const b = parseFloat(String(trozos[1]).trim().replace(",", "."));

    if (!isNaN(a) && !isNaN(b) && a > 0 && b >= 0) {
      const qty = Math.round(a);
      const w = Number(b.toFixed(5));
      const key = `GEN_${w}`;
      if (!map[key]) {
        map[key] = { product: key, quantity: 0, weight: w, __generic: true };
      }
      map[key].quantity += qty;
    }
  }

  return Object.values(map);
}

// Convierte `items` a líneas de pedido con pesos conocidos
function orderFromItems(itemsArr) {
  const parsedItems = parseItemsInput(itemsArr);
  if (!parsedItems) {
    throw new Error("El campo 'items' debe ser un arreglo válido o un JSON parseable.");
  }

  const acc = {};

  for (let i = 0; i < parsedItems.length; i++) {
    const row = parsedItems[i] || {};
    const rawProd = String(row.producto ?? row.product ?? "").trim();
    const qty = Number(row.cantidad ?? row.qty ?? 0);

    if (!rawProd || !qty) continue;

    const prod = canonicalizeProductName(rawProd);
    const w = WEIGHT_BY_PRODUCT[prod];

    if (typeof w !== "number") {
      throw new Error(`Producto desconocido o sin peso configurado: "${rawProd}"`);
    }

    if (!acc[prod]) {
      acc[prod] = { product: prod, quantity: 0, weight: w };
    }
    acc[prod].quantity += qty;
  }

  return Object.values(acc);
}

// Arma salida legible por IA
function buildOutput(boxes) {
  const outBoxes = [];
  let totalCost = 0;

  for (let i = 0; i < boxes.length; i++) {
    const b = boxes[i];
    const peso = Number(b.peso.toFixed(2));
    const costo = costoPorPeso(peso);
    totalCost += (costo || 0);

    const contenidoPretty = {};
    for (const k in b.contenido) {
      if (CATEGORY_BY_PRODUCT[k] === "OTROS_0KG") {
        contenidoPretty["Otros_0kg"] = (contenidoPretty["Otros_0kg"] || 0) + b.contenido[k];
      } else {
        contenidoPretty[k] = b.contenido[k];
      }
    }

    outBoxes.push({
      indice: i + 1,
      peso_total_kg: peso,
      costo_envio: costo,
      costo_envio_str: costo != null ? `$${costo}` : null,
      contenido: contenidoPretty
    });
  }

  return {
    cajas: outBoxes,
    cantidad_cajas: outBoxes.length,
    costo_total_envio: totalCost,
    costo_total_envio_str: `$${totalCost}`,
    resumen_cajas: outBoxes.map(b => `Caja ${b.indice}: ${b.costo_envio_str}`)
  };
}

// ====== Ejecución por item ======
const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json || {};
  let orderLines;

  if (input.items !== undefined) {
    // Formato recomendado
    orderLines = orderFromItems(input.items);
  } else if (typeof input.cuentas === "string") {
    // Compatibilidad (solo peso, sin categorías)
    orderLines = orderFromCuentasStr(input.cuentas);
  } else {
    results.push({
      json: {
        error: "Entrada inválida: provea 'items' (preferido) o 'cuentas' (compatibilidad)."
      }
    });
    continue;
  }

  const boxes = packBoxes(orderLines);

  for (let b = 0; b < boxes.length; b++) {
    const peso = Number(boxes[b].peso.toFixed(4));
    if (peso > LIMITS.MAX_PER_BOX_WEIGHT_KG + 1e-6) {
      throw new Error(`Caja ${b + 1} excede ${LIMITS.MAX_PER_BOX_WEIGHT_KG} kg (${peso} kg).`);
    }
  }

  const salida = buildOutput(boxes);
  results.push({ json: salida });
}

return results;

/**
 * n8n Code node (Run Once for Each Item)
 *
 * Entrada por item (preferido):
 * {
 *   "items": [
 *     { "producto": "Cilindros", "cantidad": 320 },
 *     { "producto": "Sandalias Delgadas", "cantidad": 150 },
 *     { "producto": "Pantuflas", "cantidad": 80 },
 *     { "producto": "Mandiles", "cantidad": 20 }
 *   ]
 * }
 *
 * Compatibilidad (sin nombres):
 * { "cuentas": "50 x 0.15, 75 x 0.15" }
 *
 * Salida por item:
 * {
 *   "cajas": [
 *     {
 *       "indice": 1,
 *       "peso_total_kg": 18.75,
 *       "costo_envio": 350,
 *       "costo_envio_str": "$350",
 *       "contenido": { "Cilindros": 250, "Sandalias Delgadas": 50, "Pantuflas": 0, "Otros_0kg": 20 }
 *     },
 *     ...
 *   ],
 *   "cantidad_cajas": 3,
 *   "costo_total_envio": 900,
 *   "costo_total_envio_str": "$900",
 *   "resumen_cajas": ["Caja 1: $350", "Caja 2: $300", "Caja 3: $250"]
 * }
 */

// ====== Config editable ======

// Pesos por producto (kg)
const WEIGHT_BY_PRODUCT = {
  "Mandiles": 0,
  "Kits Anticrudas": 0,
  "Costales": 0,
  "Cilindros": 0.14,
  "Sandalias Delgadas": 0.15,
  "Sandalias Gruesas": 0.15,
  "Pantuflas": 0.15
};

// Categoría por producto (para aplicar límites). Ajustá si Pantuflas NO debe contar como Sandalia.
const CATEGORY_BY_PRODUCT = {
  "Cilindros": "CILINDROS",
  "Sandalias Delgadas": "SANDALIAS",
  "Sandalias Gruesas": "SANDALIAS",
  "Pantuflas": "SANDALIAS",

  // Los de 0 kg (sin restricciones explícitas)
  "Mandiles": "OTROS_0KG",
  "Kits Anticrudas": "OTROS_0KG",
  "Costales": "OTROS_0KG"
};

// Límites por caja
const LIMITS = {
  MAX_PER_BOX_WEIGHT_KG: 35,
  MAX_CILINDROS_PER_BOX: 250,
  MAX_SANDALIAS_PER_BOX: 200,
  MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX: 200
};

// Rangos de costo por peso total de la caja (kg)
// Nota: se respetan tus bordes tal cual (p.ej. 5–7 incluye 7; 7.1–15 empieza en 7.1)
function costoPorPeso(pesoKg) {
  const p = Number(pesoKg.toFixed(2));
  if (p >= 0 && p <= 4.99) return 250;
  if (p >= 5 && p <= 7) return 280;
  if (p > 7.1 && p <= 12) return 300;      // 7.01..15 (tu tabla pone 7.1, aquí usamos >7 para cubrir decimales)
  if (p > 12.1 && p <= 19.99) return 350;  // 15.01..27.99
  if (p >= 20 && p <= 35) return 400;
  // Si se pasa de 35, no debería suceder porque partimos, pero por seguridad:
  return null;
}

// ====== Utilidades ======

function cloneEmptyBoxState() {
  return {
    peso: 0,
    cil: 0,            // # Cilindros en la caja
    sand: 0,           // # Sandalias (cualquier tipo) en la caja
    combSC: 0,         // combinadas sandalias + cilindros
    contenido: {},     // { producto: unidades }
  };
}

function addToBox(box, product, qty, weightPerUnit) {
  if (!box.contenido[product]) box.contenido[product] = 0;
  box.contenido[product] += qty;
  box.peso += qty * weightPerUnit;
  // contadores por categoría
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  if (cat === "CILINDROS") {
    box.cil += qty;
    box.combSC += qty;
  } else if (cat === "SANDALIAS") {
    box.sand += qty;
    box.combSC += qty;
  }
}

// capacidad restante por restricciones duras (unidades posibles adicionales)
function capacityForProductInBox(box, product, weightPerUnit) {
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  let cap = Infinity;

  // Peso
  if (weightPerUnit > 0) {
    const weightLeft = LIMITS.MAX_PER_BOX_WEIGHT_KG - box.peso;
    const byWeight = Math.floor(weightLeft / weightPerUnit);
    cap = Math.min(cap, Math.max(0, byWeight));
  }

  // Límites por categoría
  if (cat === "CILINDROS") {
    cap = Math.min(cap, LIMITS.MAX_CILINDROS_PER_BOX - box.cil);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "SANDALIAS") {
    cap = Math.min(cap, LIMITS.MAX_SANDALIAS_PER_BOX - box.sand);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "OTROS_0KG") {
    // Sin límite de unidades y sin peso (0 kg), no afecta restricciones
    cap = Infinity;
  } else {
    // Otros productos con peso pero sin límite de unidades específico: solo pesa
    // (Si en el futuro aparecen límites, agregarlos aquí)
  }

  return Math.max(0, cap);
}

// Empaquetado: “first-fit” con llenado por tandas (eficiente y simple)
function packBoxes(orderLines) {
  // orderLines: [{ product, quantity, weight }]
  const boxes = [];
  let currentBox = cloneEmptyBoxState();

  // Estrategia de orden:
  // 1) Productos con restricciones y peso más “críticos” primero (Sandalias/Cilindros 0.15/0.14)
  // 2) Luego otros con peso
  // 3) Al final 0 kg (no molestan, pero los dejamos para el final para no romper límites combinados)
  const lines = orderLines.slice().sort((a,b) => {
    const rank = (x) => {
      const cat = CATEGORY_BY_PRODUCT[x.product] || "OTROS";
      if (cat === "CILINDROS" || cat === "SANDALIAS") return 0; // más prioritarios
      if (x.weight > 0) return 1;
      return 2; // 0 kg
    };
    const rA = rank(a), rB = rank(b);
    if (rA !== rB) return rA - rB;
    // dentro de la misma categoría, ordenar por peso desc (llena más rápido)
    return (b.weight || 0) - (a.weight || 0);
  });

  // Haremos múltiples pasadas hasta consumir todas las cantidades
  // En cada pasada intentamos meter tandas máximas en la caja actual
  const remaining = {};
  for (const ln of lines) remaining[ln.product] = (remaining[ln.product] || 0) + ln.quantity;

  // Función auxiliar: ¿queda algo?
  function hasRemaining() {
    for (const k in remaining) if (remaining[k] > 0) return true;
    return false;
  }

  while (hasRemaining()) {
    let packedSomething = false;

    for (let i = 0; i < lines.length; i++) {
      const { product, weight } = lines[i];
      let need = remaining[product];
      if (!need) continue;

      let cap = capacityForProductInBox(currentBox, product, weight);
      if (cap <= 0) continue;

      // Para tandas grandes, no iteramos unidad por unidad: metemos lo máximo posible
      const toPut = Math.min(need, cap);
      if (toPut > 0) {
        addToBox(currentBox, product, toPut, weight);
        remaining[product] -= toPut;
        packedSomething = true;
      }
    }

    // Si no entró nada más en esta caja o ya consumimos todo, cerramos caja
    if (!packedSomething || !hasRemaining()) {
      // Empujar caja si tiene algo (o si es la última con contenido)
      const hasContent = Object.keys(currentBox.contenido).length > 0;
      if (hasContent) {
        boxes.push(currentBox);
      }
      if (hasRemaining()) {
        currentBox = cloneEmptyBoxState(); // abrir nueva caja para seguir
      }
    }
  }

  return boxes;
}

// Traduce "cuentas" -> líneas de pedido genéricas (sin nombres de producto)
function orderFromCuentasStr(cuentasStr) {
  // Sin nombres => no podemos aplicar límites por tipo, solo peso y 35 kg
  // Mapeará todo a un pseudo-producto "GENÉRICO_w=..."
  const parts = (cuentasStr || "").split(",");
  const map = {}; // key por peso
  for (let i = 0; i < parts.length; i++) {
    const expr = (parts[i] || "").trim();
    if (!expr) continue;
    const trozos = expr.split(/x|X|×|\*/);
    if (trozos.length < 2) continue;
    const a = parseFloat(String(trozos[0]).trim().replace(",", "."));
    const b = parseFloat(String(trozos[1]).trim().replace(",", "."));
    if (!isNaN(a) && !isNaN(b) && a > 0 && b >= 0) {
      const qty = Math.round(a); // a = cantidad (entera)
      const w = Number(b.toFixed(5)); // b = kg por unidad
      const key = `GEN_${w}`;
      if (!map[key]) map[key] = { product: key, quantity: 0, weight: w, __generic: true };
      map[key].quantity += qty;
    }
  }
  return Object.values(map);
}

// Convierte el input preferido `items` a líneas de pedido con pesos conocidos
function orderFromItems(itemsArr) {
  const acc = {};
  for (let i = 0; i < itemsArr.length; i++) {
    const prod = String(itemsArr[i].producto || "").trim();
    const qty = Number(itemsArr[i].cantidad || 0);
    if (!prod || !qty) continue;
    const w = WEIGHT_BY_PRODUCT[prod];
    if (typeof w !== "number") {
      throw new Error(`Producto desconocido o sin peso configurado: "${prod}"`);
    }
    const key = prod;
    if (!acc[key]) acc[key] = { product: prod, quantity: 0, weight: w };
    acc[key].quantity += qty;
  }
  return Object.values(acc);
}

// Arma salida legible por IA
function buildOutput(boxes) {
  const outBoxes = [];
  let totalCost = 0;

  for (let i = 0; i < boxes.length; i++) {
    const b = boxes[i];
    // Redondeo suave del peso a 2 decimales
    const peso = Number(b.peso.toFixed(2));
    const costo = costoPorPeso(peso);
    totalCost += (costo || 0);

    // Normalizar nombres para 0 kg
    const contenidoPretty = {};
    for (const k in b.contenido) {
      if (CATEGORY_BY_PRODUCT[k] === "OTROS_0KG") {
        // agrupar todo 0kg bajo una etiqueta si preferís
        contenidoPretty["Otros_0kg"] = (contenidoPretty["Otros_0kg"] || 0) + b.contenido[k];
      } else {
        contenidoPretty[k] = b.contenido[k];
      }
    }

    outBoxes.push({
      indice: i + 1,
      peso_total_kg: peso,
      costo_envio: costo,
      costo_envio_str: costo != null ? `$${costo}` : null,
      contenido: contenidoPretty
    });
  }

  return {
    cajas: outBoxes,
    cantidad_cajas: outBoxes.length,
    costo_total_envio: totalCost,
    costo_total_envio_str: `$${totalCost}`,
    resumen_cajas: outBoxes.map(b => `Caja ${b.indice}: ${b.costo_envio_str}`)
  };
}

// ====== Ejecución por item ======
const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json || {};

  let orderLines;

  if (Array.isArray(input.items)) {
    // Formato recomendado
    orderLines = orderFromItems(input.items);
  } else if (typeof input.cuentas === "string") {
    // Compatibilidad (solo peso)
    orderLines = orderFromCuentasStr(input.cuentas);
    // En compatibilidad, forzamos categorías "GEN" sin límites de unidades (solo 35 kg por caja)
    // Sobrescribimos CATEGORY_BY_PRODUCT temporalmente a "OTROS"
    // Implementamos la lógica de empaque usando solo peso (packBoxes usa limits de sand/cil solo si hay categorías).
    // Para lograrlo, pasamos los GEN_* que no están en CATEGORY_BY_PRODUCT => caen en "OTROS" y solo pesan.
  } else {
    results.push({ json: { error: "Entrada inválida: provea 'items' o 'cuentas'." } });
    continue;
  }

  // Empaquetar
  const boxes = packBoxes(orderLines);

  // Seguridad: ninguna caja debe superar 35 kg
  for (let b = 0; b < boxes.length; b++) {
    const peso = Number(boxes[b].peso.toFixed(4));
    if (peso > LIMITS.MAX_PER_BOX_WEIGHT_KG + 1e-6) {
      throw new Error(`Caja ${b + 1} excede ${LIMITS.MAX_PER_BOX_WEIGHT_KG} kg (${peso} kg).`);
    }
  }

  const salida = buildOutput(boxes);

  results.push({ json: salida });
}

return results;

// n8n Code node (Run Once for Each Item)
// Entrada esperada por item:
// { json: { cuentas: "50 x 0.15, 75 x 0.15, ..." } }

function calcularTotalKg(cuentasStr) {
  if (!cuentasStr || typeof cuentasStr !== 'string') return 0;

  // Divide por comas (lista de multiplicaciones)
  const partes = cuentasStr.split(',');

  let total = 0;
  for (let i = 0; i < partes.length; i++) {
    const expr = (partes[i] || '').trim();
    if (!expr) continue;

    // Soporta "x", "X", "×" o "*", con espacios
    const trozos = expr.split(/x|X|×|\*/);

    if (trozos.length < 2) continue; // si no hay 2 números, se salta

    // Permite "0.15" o "0,15"
    const a = parseFloat(String(trozos[0]).trim().replace(',', '.'));
    const b = parseFloat(String(trozos[1]).trim().replace(',', '.'));

    if (!isNaN(a) && !isNaN(b)) {
      total += a * b;
    }
  }

  // Redondeo “limpio” a 2 decimales para evitar ruido flotante
  return Number(total.toFixed(2));
}

function costoPorRango(totalKg) {
  // Rangos solicitados:
  // 0–4.99 => 200
  // 5–7 => 250
  // 7.1–15 => 300
  // 15.1–27.99 => 350
  // 28–35 => 400
  if (totalKg >= 0 && totalKg <= 4.99) return 200;
  if (totalKg >= 5 && totalKg <= 7) return 250;
  if (totalKg >= 7.1 && totalKg <= 15) return 300;
  if (totalKg >= 15.1 && totalKg <= 27.99) return 350;
  if (totalKg >= 28 && totalKg <= 35) return 400;

  // Fuera de rango (por ahora lo dejamos en null para tratarlo luego)
  return null;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const cuentasStr = items[i].json?.cuentas;
  const totalKg = calcularTotalKg(cuentasStr);
  const costo = costoPorRango(totalKg);

  out.push({
    json: {
      total_kg: totalKg,               // Total de kg calculado (útil para debug/reportes)
      costo_envio: costo,              // Número
      costo_envio_str: costo !== null ? `$${costo}` : null // "$400" como pediste
    }
  });
}

return out;
